import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        long[] diff = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) {
            long b = nextLong();
            total += b;
            diff[i] = a[i] - b;
        }
        // Start with everything on person 2, then move the k largest gains to person 1.
        Arrays.sort(diff);
        for (int i = 0; i < k; i++) total += diff[n - 1 - i];
        System.out.println(total);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	diff := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	var total int64
	for i := range a {
		b := nextInt()
		total += b
		diff[i] = a[i] - b
	}
	// Start with everything on person 2, then move the k largest gains to person 1.
	sort.Slice(diff, func(i, j int) bool { return diff[i] > diff[j] })
	for i := 0; i < k; i++ {
		total += diff[i]
	}
	fmt.Println(total)
}
